import re
import os


def task_func(request):
    if not isinstance(request, str):
        return "HTTP/1.1 400 Bad Request\r\n\r\nInvalid request"

    match = re.fullmatch(r"GET\s+(/\S*)\s+HTTP/\d+(?:\.\d+)?", request.strip())
    if not match:
        return "HTTP/1.1 400 Bad Request\r\n\r\nInvalid request"

    path = match.group(1).split("?", 1)[0]
    filename = path.lstrip("/")

    if not filename or "\x00" in filename:
        return "HTTP/1.1 400 Bad Request\r\n\r\nInvalid request"

    normalized_path = os.path.normpath(filename)
    if normalized_path == ".." or normalized_path.startswith(".." + os.sep):
        return "HTTP/1.1 400 Bad Request\r\n\r\nInvalid request"

    if not os.path.isfile(normalized_path):
        return "HTTP/1.1 404 Not Found\r\n\r\nFile not found"

    try:
        with open(normalized_path, "r", encoding="utf-8") as file:
            content = file.read()
    except (OSError, UnicodeDecodeError):
        return "HTTP/1.1 404 Not Found\r\n\r\nFile not found"

    return (
        f"HTTP/1.1 200 OK\r\n"
        f"Content-Length: {len(content.encode('utf-8'))}\r\n"
        f"\r\n{content}"
    )

