def task_func(file_path):
    if not isinstance(file_path, str) or not file_path.lower().endswith(".csv"):
        raise ValueError("The input file must have a .csv extension.")

    try:
        with open(file_path, "r", newline="", encoding="utf-8") as csv_file:
            rows = [tuple(row) for row in csv.reader(csv_file, strict=True)]
    except csv.Error as exc:
        raise ValueError("The CSV file is not properly formatted.") from exc

    row_counts = Counter(rows)
    duplicate_rows = {
        row: count for row, count in row_counts.items() if count > 1
    }

    dataframe = pd.DataFrame(
        [
            {"row": ", ".join(row), "count": count}
            for row, count in duplicate_rows.items()
        ],
        columns=["row", "count"],
    )

    ax = dataframe.plot(
        x="row",
        y="count",
        kind="bar",
        legend=False,
        title="Duplicate CSV Rows",
    )
    ax.set_xlabel("Duplicate Row")
    ax.set_ylabel("Count")
    plt.tight_layout()

    return duplicate_rows, ax

