import re
import random


def task_func(s: str, seed: int = 0) -> pd.DataFrame:
    columns = ["ID", "Quantity", "Code", "Price", "Product", "Description"]
    product_names = ["Apple", "Banana", "Orange", "Pear", "Grape"]
    rng = random.Random(seed)
    code_to_product = {}
    records = []

    for line_number, segment in enumerate(s.splitlines(), start=1):
        if not segment.strip():
            continue

        parts = re.split(r"\s+", segment.strip(), maxsplit=4)
        if len(parts) != 5:
            raise ValueError(
                f"Invalid product data on line {line_number}: "
                "expected ID, quantity, code, price, and description"
            )

        product_id, quantity, code, price, description = (
            part.rstrip() for part in parts
        )

        try:
            quantity = int(quantity)
            price = int(price)
        except ValueError as exc:
            raise ValueError(
                f"Invalid quantity or price on line {line_number}"
            ) from exc

        if code not in code_to_product:
            code_to_product[code] = rng.choice(product_names)

        records.append(
            {
                "ID": product_id,
                "Quantity": quantity,
                "Code": code,
                "Price": price,
                "Product": code_to_product[code],
                "Description": description,
            }
        )

    return pd.DataFrame(records, columns=columns)

import itertools
import math
from pandas import Series


def task_func(elements, subset_size, top_n=2):
    if subset_size < 0 or subset_size > len(elements):
        return 1, Series(dtype=int)

    if subset_size == 0:
        return 1, Series([0]).head(top_n)

    subset_sums = [
        sum(subset)
        for subset in itertools.combinations(elements, subset_size)
    ]

    product_of_sums = math.prod(subset_sums)
    top_sums = Series(sorted(subset_sums, reverse=True)[:top_n])

    return product_of_sums, top_sums

import subprocess
import os
import signal
import time


def task_func(process_name: str) -> int:
    if not process_name:
        return 0

    try:
        result = subprocess.run(
            ["pgrep", "-x", process_name],
            capture_output=True,
            text=True,
            check=False,
        )
    except (FileNotFoundError, OSError):
        return 0

    pids = []
    for line in result.stdout.splitlines():
        try:
            pid = int(line.strip())
        except ValueError:
            continue

        if pid != os.getpid():
            pids.append(pid)

    stopped = 0
    for pid in pids:
        try:
            os.kill(pid, signal.SIGTERM)
            stopped += 1
        except (ProcessLookupError, PermissionError, OSError):
            continue

    if stopped:
        time.sleep(1)

    return stopped

