def task_func(P, T):
    if not isinstance(P, (np.ndarray, np.matrix)):
        raise TypeError("P must be a NumPy array or matrix.")
    if not isinstance(T, (np.ndarray, np.matrix)):
        raise TypeError("T must be a NumPy array or matrix.")

    P = np.asarray(P)
    T = np.asarray(T)

    if P.ndim != 2:
        raise ValueError("P must be two-dimensional.")
    if T.ndim != 3:
        raise ValueError("T must be three-dimensional.")
    if P.shape[1] != T.shape[0]:
        raise ValueError(
            "The number of columns in P must match the first dimension of T."
        )

    result = np.einsum("ij,jkl->ik", P, T)

    _, ax = plt.subplots()
    sns.heatmap(result, ax=ax)
    ax.set_title("Matrix-Tensor Product")

    return result, ax

import subprocess
import os
import shutil
from glob import glob


def task_func(src_folder, dst_folder):
    failed_files = []

    if not os.path.isdir(src_folder):
        return {
            "success": False,
            "message": f"Source folder does not exist: {src_folder}",
            "failed_files": [],
        }

    try:
        os.makedirs(dst_folder, exist_ok=True)
    except OSError as exc:
        files = [
            path for path in glob(os.path.join(src_folder, "*"))
            if os.path.isfile(path)
        ]
        return {
            "success": False,
            "message": f"Could not create destination folder: {exc}",
            "failed_files": [os.path.basename(path) for path in files],
        }

    files = [
        path for path in glob(os.path.join(src_folder, "*"))
        if os.path.isfile(path)
    ]

    for file_path in files:
        filename = os.path.basename(file_path)
        compressed_path = file_path + ".gz"
        destination_path = os.path.join(dst_folder, filename + ".gz")

        try:
            process = subprocess.Popen(
                ["gzip", "-f", file_path],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.PIPE,
            )
            _, stderr = process.communicate()

            if process.returncode != 0:
                failed_files.append(filename)
                if os.path.exists(compressed_path):
                    os.remove(compressed_path)
                continue

            if os.path.abspath(compressed_path) != os.path.abspath(destination_path):
                shutil.move(compressed_path, destination_path)

        except (OSError, subprocess.SubprocessError, shutil.Error):
            failed_files.append(filename)
            if os.path.exists(compressed_path):
                try:
                    os.remove(compressed_path)
                except OSError:
                    pass

    success = not failed_files
    if success:
        message = (
            "No files were found; operation completed successfully."
            if not files
            else "All files were compressed and moved successfully."
        )
    else:
        message = "Some files could not be compressed or moved."

    return {
        "success": success,
        "message": message,
        "failed_files": failed_files,
    }

import random
import string
import pandas as pd


def task_func(data_list, seed=0):
    rng = random.Random(seed)
    modified_strings = []

    for value in data_list:
        candidates = []
        start = 0

        for index in range(len(value) + 1):
            if index == len(value) or value[index] == ",":
                if start < index:
                    candidates.append((start, index))
                start = index + 1

        if candidates:
            substring_start, substring_end = rng.choice(candidates)
            replacement = "".join(
                rng.choices(
                    string.ascii_lowercase,
                    k=substring_end - substring_start,
                )
            )
            modified = (
                value[:substring_start]
                + replacement
                + value[substring_end:]
            )
        else:
            modified = value

        modified_strings.append(modified)

    return pd.DataFrame(
        {
            "Original String": list(data_list),
            "Modified String": modified_strings,
        }
    )

import os
import glob
import shutil


def task_func(directory, archive_dir='archive'):
    errors = []

    if not os.path.isdir(directory):
        return False, [f"Directory does not exist: {directory}"]

    json_files = [
        path for path in glob.glob(os.path.join(directory, "*.json"))
        if os.path.isfile(path)
    ]

    if not json_files:
        return True, errors

    try:
        os.makedirs(archive_dir, exist_ok=True)
    except Exception as exc:
        return False, [
            f"Failed to move {path}: {exc}"
            for path in json_files
        ]

    for path in json_files:
        try:
            shutil.move(path, archive_dir)
        except Exception as exc:
            errors.append(f"Failed to move {path}: {exc}")

    return not errors, errors

