def task_func(MIN_WORDS, MAX_WORDS, WORDS_POOL):
    if MIN_WORDS < 0 or MAX_WORDS < MIN_WORDS:
        raise ValueError("Invalid word count range.")
    if not WORDS_POOL and MAX_WORDS > 0:
        raise ValueError("WORDS_POOL cannot be empty.")

    length = random.randint(MIN_WORDS, MAX_WORDS)
    first_half = [random.choice(WORDS_POOL) for _ in range((length + 1) // 2)]
    words = first_half + first_half[:length // 2][::-1]

    return " ".join(words)

