    anova_results = pd.DataFrame(columns=["F-value", "P-value"])

    if len(data.columns) >= 2:
        results = {}
        for index, first_column in enumerate(data.columns):
            for second_column in data.columns[index + 1:]:
                pair_data = data[[first_column, second_column]].dropna()
                f_value, p_value = f_oneway(
                    pair_data[first_column],
                    pair_data[second_column],
                )
                results[(first_column, second_column)] = {
                    "F-value": f_value,
                    "P-value": p_value,
                }

        anova_results = pd.DataFrame.from_dict(results, orient="index")
        anova_results.index.names = ["Column 1", "Column 2"]

    return means, std_devs, axes, anova_results

