    fake.seed_instance(seed)

    event_name = fake.catch_phrase()
    event_datetime = datetime.fromtimestamp(epoch_milliseconds / 1000)

    timezone_pattern = re.compile(r"^UTC([+-])(\d{2}):(\d{2})$")
    valid_timezones = []

    for timezone in timezones or []:
        if timezone in pytz.all_timezones:
            valid_timezones.append(timezone)
