        match = timezone_pattern.fullmatch(timezone)
        if match:
            hours = int(match.group(2))
            minutes = int(match.group(3))
            if hours <= 23 and minutes <= 59:
                valid_timezones.append(timezone)

    selected_timezone = (
        fake.random_element(valid_timezones) if valid_timezones else "UTC"
    )

    return {
        event_name: [
            {
                "date": event_datetime.strftime("%Y-%m-%d"),
                "time": event_datetime.strftime("%H:%M:%S"),
                "timezone": selected_timezone,
