import os
import hashlib
import json
from pathlib import Path


def task_func(directory: str) -> str:
    base_dir = Path(directory).resolve(strict=True)

    if not base_dir.is_dir():
        raise NotADirectoryError(f"Not a directory: {base_dir}")

    hashes = {}

    for root, _, filenames in os.walk(base_dir):
        for filename in filenames:
            file_path = Path(root) / filename

            if file_path == base_dir / "hashes.json":
                continue

            relative_path = file_path.relative_to(base_dir)
            digest = hashlib.sha256()

            with file_path.open("rb") as file:
                for chunk in iter(lambda: file.read(1024 * 1024), b""):
                    digest.update(chunk)

            hashes[str(relative_path)] = digest.hexdigest()

    output_path = base_dir / "hashes.json"

    with output_path.open("w", encoding="utf-8") as file:
        json.dump(dict(sorted(hashes.items())), file, indent=2, ensure_ascii=False)
        file.write("\n")

    return str(output_path)

