import pandas as pd
from random import randint, seed


def task_func(dictionary, item, sample_size=None, random_seed=None):
    """
    Convert a dictionary to a DataFrame and find positions of an item.

    Returns:
        tuple: (list of (row index, column name) positions, DataFrame)
    """
    dataframe = pd.DataFrame(dictionary)
    positions = []

    for row_index, row in dataframe.iterrows():
        for column_name, value in row.items():
            try:
                matches = value == item
                if pd.isna(matches):
                    matches = False
            except (TypeError, ValueError):
                matches = False

            if matches:
                positions.append((row_index, column_name))

    if sample_size is not None:
        if sample_size < 0:
            raise ValueError("sample_size must be non-negative")

        seed(random_seed)
        sample_size = min(sample_size, len(positions))
        sampled_positions = []

        for _ in range(sample_size):
            index = randint(0, len(positions) - 1)
            sampled_positions.append(positions.pop(index))

        positions = sampled_positions

    return positions, dataframe

