import subprocess
import time
import json
import platform

LOGFILE_PATH = "logfile.log"


def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")

    start_time = time.time()
    records = []

    if platform.system() == "Windows":
        command = "wmic cpu get loadpercentage"
    else:
        command = "top -bn1 | grep 'Cpu(s)'"

    while time.time() - start_time < duration:
        output = subprocess.check_output(command, shell=True)

        if isinstance(output, bytes):
            output = output.decode(errors="replace")

        if platform.system() == "Windows":
            usage = None
            for line in output.splitlines():
                line = line.strip()
                try:
                    usage = float(line)
                    break
                except ValueError:
                    continue
            if usage is None:
                raise ValueError("Unable to parse CPU usage")
        else:
            usage = None
            for token in output.replace(",", " ").split():
                if "%us" in token:
                    try:
                        usage = float(token.replace("%us", ""))
                        break
                    except ValueError:
                        continue

            if usage is None:
                raise ValueError("Unable to parse CPU usage")

        records.append({
            "timestamp": time.time(),
            "cpu_usage": usage
        })

        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, "w", encoding="utf-8") as logfile:
            json.dump(records, logfile, indent=2)
    except IOError:
        return None

    return LOGFILE_PATH

