    future_time = np.arange(periods_count, periods_count * 2).reshape(-1, 1)
    return np.asarray(model.predict(future_time))

import re
import glob
from docx import Document

def task_func(directory_path: str) -> int:
    patterns = [
        f"{directory_path.rstrip('/\\\\')}/*.docx",
        f"{directory_path.rstrip('/\\\\')}/*.DOCX",
    ]

    file_paths = []
    seen_files = set()
    for pattern in patterns:
        for file_path in glob.glob(pattern):
            if file_path not in seen_files:
                seen_files.add(file_path)
                file_paths.append(file_path)

    processed_files = 0

    def process_container(container, seen_paragraphs):
        for paragraph in container.paragraphs:
            paragraph_id = id(paragraph._p)
            if paragraph_id in seen_paragraphs:
                continue

            seen_paragraphs.add(paragraph_id)
            for run in paragraph.runs:
                run.text = re.sub(r'"', r'\\"', run.text)

        for table in container.tables:
            for row in table.rows:
                for cell in row.cells:
                    process_container(cell, seen_paragraphs)

    for file_path in file_paths:
        document = Document(file_path)
        seen_paragraphs = set()

        process_container(document, seen_paragraphs)

        for section in document.sections:
            process_container(section.header, seen_paragraphs)
            process_container(section.first_page_header, seen_paragraphs)
            process_container(section.even_page_header, seen_paragraphs)
            process_container(section.footer, seen_paragraphs)
            process_container(section.first_page_footer, seen_paragraphs)
            process_container(section.even_page_footer, seen_paragraphs)

        document.save(file_path)
        processed_files += 1

    return processed_files

