def task_func(dic):
    if not dic:
        raise ValueError("The input dictionary cannot be empty.")

    locations = list(dic.items())
    first_coordinates = locations[0][1]

    map_object = folium.Map(location=first_coordinates, zoom_start=4)

    for name, coordinates in locations:
        folium.Marker(
            location=coordinates,
            popup=str(name),
            tooltip=str(name),
        ).add_to(map_object)

    distances = {}
    for index, (name_a, coordinates_a) in enumerate(locations):
        for name_b, coordinates_b in locations[index + 1:]:
            distances[(name_a, name_b)] = geodesic(
                coordinates_a, coordinates_b
            ).kilometers

    return map_object, distances

import os
import pathlib
from hashlib import md5
import unicodedata
def task_func(directory):
    result = {}

    for file_path in pathlib.Path(directory).iterdir():
        if file_path.is_file():
            normalized_name = (
                unicodedata.normalize("NFKD", file_path.name)
                .encode("ascii", "ignore")
                .decode("ascii")
            )

            file_hash = md5()
            with open(file_path, "rb") as file:
                for chunk in iter(lambda: file.read(8192), b""):
                    file_hash.update(chunk)

            result[normalized_name] = {
                "Size": os.path.getsize(file_path),
                "MD5 Hash": file_hash.hexdigest(),
            }

    return result

import pandas as pd
import os
import numpy as np
import ast


def task_func(directory):
    csv_files = []

    for root, _, files in os.walk(directory):
        for filename in files:
            if filename.lower().endswith(".csv"):
                csv_files.append(os.path.join(root, filename))

    if not csv_files:
        columns = ["email", "list", "sum", "mean", "median"]
        return pd.DataFrame(columns=columns), None

    csv_path = min(
        csv_files,
        key=lambda path: (-len(os.path.basename(path)), os.path.basename(path), path),
    )

    dataframe = pd.read_csv(csv_path)
    dataframe["list"] = dataframe["list"].apply(ast.literal_eval)

    def calculate_statistics(values):
        values = np.asarray(values, dtype=float)

        if values.size == 0:
            return pd.Series({"sum": 0.0, "mean": np.nan, "median": np.nan})

        return pd.Series(
            {
                "sum": np.sum(values),
                "mean": np.mean(values),
                "median": np.median(values),
            }
        )

    dataframe[["sum", "mean", "median"]] = dataframe["list"].apply(
        calculate_statistics
    )

    valid_medians = dataframe["median"].dropna()
    valid_medians = valid_medians[np.isfinite(valid_medians)]

    if valid_medians.empty:
        return dataframe, None

    ax = dataframe["median"].plot.hist()
    return dataframe, ax

