from sklearn.cluster import KMeans
from sklearn.feature_extraction.text import CountVectorizer


def task_func(df):
    title_column = "title" if "title" in df.columns else "Title"
    content_column = "content" if "content" in df.columns else "Content"

    titles = df[title_column].fillna("").astype(str)
    mask = titles.str.contains(r"\b(?:how|what)\b", case=False, regex=True)
    filtered_content = df.loc[mask, content_column].fillna("").astype(str)

    if filtered_content.empty:
        return []

    vectorizer = CountVectorizer()
    try:
        vectors = vectorizer.fit_transform(filtered_content)
    except ValueError:
        return [0] * len(filtered_content)

    n_clusters = min(2, len(filtered_content))
    if n_clusters == 1:
        return [0]

    model = KMeans(n_clusters=n_clusters, random_state=42, n_init=10)
    return model.fit_predict(vectors).tolist()

import binascii
import hashlib
import re
import os

OUTPUT_DIR = './output'

def task_func(directory: str, pattern: str = r"(?<!Distillr)\\AcroTray\.exe") -> dict:
    regex = re.compile(pattern)
    hashes = {}

    for root, _, files in os.walk(directory):
        for filename in files:
            file_path = os.path.join(root, filename)
            if regex.search(file_path):
                with open(file_path, "rb") as file:
                    digest = hashlib.sha256(file.read()).digest()
                hashes[file_path] = binascii.hexlify(digest).decode("ascii")

    return hashes

import re
import json
import requests


def task_func(data_url: str) -> list:
    try:
        response = requests.get(data_url)
        data = response.text
        json.loads(data)

        bracket_depth = 0
        in_string = False
        escaped = False
        depths = [0] * len(data)

        for index, char in enumerate(data):
            depths[index] = bracket_depth

            if in_string:
                if escaped:
                    escaped = False
                elif char == "\\":
                    escaped = True
                elif char == '"':
                    in_string = False
            elif char == '"':
                in_string = True
            elif char == "[":
                bracket_depth += 1
            elif char == "]":
                bracket_depth = max(0, bracket_depth - 1)

        pattern = re.compile(
            r'"name"\s*:\s*"((?:\\.|[^"\\])*)"'
        )

        names = []
        for match in pattern.finditer(data):
            if depths[match.start()] == 0:
                names.append(json.loads(f'"{match.group(1)}"'))

        return names
    except Exception:
        return "Invalid url input"

