import pandas as pd
import statsmodels.api as sm


def task_func(
    df: pd.DataFrame, height: int, weight: int, columns: list
) -> sm.regression.linear_model.RegressionResultsWrapper:
    if df.empty:
        return None

    filtered_df = df[
        (df[columns[1]] > height) & (df[columns[2]] < weight)
    ]

    if filtered_df.empty:
        return None

    y = filtered_df[columns[0]]
    X = sm.add_constant(filtered_df[columns[1:]])

    return sm.OLS(y, X).fit()

