from collections import Counter


def task_func(data: List[Union[int, str]], repetitions: int = 1):
    if not data or repetitions <= 0:
        return {
            "mode": np.array([]),
            "count": np.array([], dtype=int),
        }

    counts = Counter(data)
    max_count = max(counts.values())
    modes = [value for value, count in counts.items() if count == max_count]

    try:
        modes.sort()
    except TypeError:
        modes.sort(key=lambda value: (type(value).__name__, str(value)))

    return {
        "mode": np.asarray(modes),
        "count": np.full(len(modes), max_count * repetitions, dtype=int),
    }

import numpy as np
import pandas as pd
from numbers import Real, Integral


def task_func(
    products,
    n_samples=100,
    sales_lower=50,
    sales_upper=200,
    profit_margin_min=0.1,
    profit_margin_max=0.5,
    random_seed=42,
):
    if not isinstance(products, list) or not all(
        isinstance(product, str) for product in products
    ):
        raise TypeError("products must be a list of strings")

    if isinstance(n_samples, bool) or not isinstance(n_samples, Integral):
        raise ValueError("n_samples must be a positive integer")
    if n_samples <= 0:
        raise ValueError("n_samples must be a positive integer")

    numeric_values = {
        "sales_lower": sales_lower,
        "sales_upper": sales_upper,
        "profit_margin_min": profit_margin_min,
        "profit_margin_max": profit_margin_max,
    }
    if any(isinstance(value, bool) or not isinstance(value, Real)
           for value in numeric_values.values()):
        raise TypeError(
            "sales and profit margin bounds must be numeric"
        )

    if sales_lower > sales_upper:
        raise ValueError("sales_lower cannot be greater than sales_upper")

    rng = np.random.default_rng(random_seed)

    sampled_products = rng.choice(products, size=n_samples)
    sales = rng.uniform(sales_lower, sales_upper, size=n_samples)
    profit_margins = rng.uniform(
        profit_margin_min, profit_margin_max, size=n_samples
    )
    profit = sales * profit_margins

    data = pd.DataFrame(
        {
            "Product": sampled_products,
            "Sales": sales,
            "Profit": profit,
        }
    )

    report = (
        data.groupby("Product", as_index=False)[["Sales", "Profit"]]
        .sum()
        .rename(
            columns={
                "Sales": "Total Sales",
                "Profit": "Total Profit",
            }
        )
    )

    report = report.set_index("Product").reindex(
        pd.unique(products), fill_value=0
    ).reset_index()

    return report.sort_values(
        "Total Profit", ascending=False, ignore_index=True
    )

