# Constants
COLUMNS = ['Column1', 'Column2', 'Column3', 'Column4', 'Column5']


def task_func(length, min_value=0, max_value=100):
    """Generate random data and return its empirical cumulative distribution function."""
    if not isinstance(length, (int, np.integer)) or isinstance(length, bool):
        raise TypeError("length must be a non-negative integer")
    if length < 0:
        raise ValueError("length must be non-negative")
    if min_value > max_value:
        raise ValueError("min_value must not exceed max_value")

    data = np.random.uniform(
        min_value,
        max_value,
        size=(length, len(COLUMNS)),
    )
    dataframe = pd.DataFrame(data, columns=COLUMNS)

    if length == 0:
        return dataframe

    return dataframe.apply(lambda column: column.rank(method="max") / length)

