import os
import sys
import importlib
from pkgutil import iter_modules


def task_func(package_name):
    try:
        package = importlib.import_module(package_name)
    except ImportError as exc:
        raise ImportError(
            f"Package '{package_name}' could not be found. "
            f"Please install it using: pip install {package_name}"
        ) from exc

    package_paths = getattr(package, "__path__", None)
    if package_paths is None:
        raise ImportError(
            f"'{package_name}' is not a package. "
            f"Please install it using: pip install {package_name}"
        )

    added_modules = []

    for package_path in package_paths:
        if package_path not in sys.path:
            sys.path.append(package_path)

        for _, module_name, _ in iter_modules([package_path]):
            if module_name not in added_modules:
                added_modules.append(module_name)

    return added_modules

