import re
import pandas as pd
from datetime import datetime


def task_func(log_file):
    pattern = re.compile(
        r"^\s*([^:\r\n]+):\s*\[([^\]]+)\]\s*-\s*(.*?)\s*$"
    )
    entries = []

    with open(log_file, "r", encoding="utf-8") as file:
        for line in file:
            match = pattern.match(line)
            if not match:
                continue

            message_type, timestamp, message = match.groups()

            try:
                datetime.strptime(timestamp, "%Y-%m-%d %H:%M:%S")
            except ValueError as exc:
                raise ValueError(
                    f"Invalid timestamp in log entry: {timestamp}"
                ) from exc

            entries.append(
                {
                    "Type": message_type.strip(),
                    "Timestamp": timestamp,
                    "Message": message,
                }
            )

    if not entries:
        raise ValueError("No valid log entries found")

    output_file = str(log_file).rsplit(".", 1)[0] + ".csv"
    pd.DataFrame(entries, columns=["Type", "Timestamp", "Message"]).to_csv(
        output_file, index=False
    )

    return output_file

