}


def task_func(url, parameters):
    """Retrieve API data, create a DataFrame, and display a correlation heatmap."""
    try:
        if not isinstance(url, str) or not url.strip():
            raise Exception("Invalid URL")

        response = requests.get(url, params=parameters, headers=HEADERS)

        if hasattr(response, "raise_for_status"):
            response.raise_for_status()
        elif getattr(response, "status_code", 200) >= 400:
            raise Exception("URL cannot be accessed")

        if hasattr(response, "json") and callable(response.json):
            data = response.json()
        else:
            data = json.loads(response.text)

        if isinstance(data, dict) and "data" in data:
            data = data["data"]

        if isinstance(data, dict):
            if not data:
                raise Exception("Empty data")
            try:
                dataframe = pd.DataFrame(data)
            except Exception:
                dataframe = pd.DataFrame([data])
        elif isinstance(data, list):
            if not data:
                raise Exception("Empty data")
            dataframe = pd.DataFrame(data)
        else:
            raise Exception("Invalid data")

        if dataframe.empty:
            raise Exception("Empty data")

        numeric_data = dataframe.select_dtypes(include="number")
        if numeric_data.empty:
            raise Exception("No numerical characteristics found")

        correlation = numeric_data.corr()
        axes = sns.heatmap(correlation, annot=True, cmap="coolwarm")
        plt.show()

        return dataframe, axes

    except Exception as exc:
        raise Exception("Unable to retrieve or process the data") from exc

import random
