import numpy as np
from datetime import datetime
import pandas as pd


def task_func(
    start_time,
    end_time,
    step,
    columns=["Timestamp", "Sensor1", "Sensor2", "Sensor3", "SensorStatus"],
    sensor_statuses=["OK", "MAINTENANCE_REQUIRED", "ERROR"],
    random_seed=42,
):
    """Generate artificial sensor readings for a range of timestamps."""

    if len(columns) != 5:
        raise ValueError("columns must contain exactly five column names")

    if not sensor_statuses:
        raise ValueError("sensor_statuses must not be empty")

    start = pd.Timestamp(start_time)
    end = pd.Timestamp(end_time)

    if isinstance(step, (int, float, np.integer, np.floating)):
        if step <= 0:
            raise ValueError("step must be positive")
        step = pd.Timedelta(seconds=float(step))

    if step <= pd.Timedelta(0):
        raise ValueError("step must be positive")

    timestamps = pd.date_range(start=start, end=end, freq=step)
    rng = np.random.default_rng(random_seed)

    timestamp_seconds = np.array(
        [timestamp.value / 1_000_000_000 for timestamp in timestamps],
        dtype=float,
    )

    noise_scale = 0.01
    sensor1 = np.sin(timestamp_seconds) + rng.normal(
        0, noise_scale, len(timestamps)
    )
    sensor2 = np.cos(timestamp_seconds) + rng.normal(
        0, noise_scale, len(timestamps)
    )
    sensor3 = np.array(
        [math.tan(value) for value in timestamp_seconds],
        dtype=float,
    ) + rng.normal(0, noise_scale, len(timestamps))

    statuses = rng.choice(sensor_statuses, size=len(timestamps))

    return pd.DataFrame(
        {
            columns[0]: timestamps,
            columns[1]: sensor1,
            columns[2]: sensor2,
            columns[3]: sensor3,
            columns[4]: statuses,
        },
        columns=columns,
    )

