import rsa
import urllib.request
import urllib.error
from hashlib import sha256


def task_func(url):
    try:
        response = urllib.request.urlopen(url)
        try:
            content = response.read()
        finally:
            response.close()
    except urllib.error.HTTPError as exc:
        raise ValueError("The server returned an HTTP error.") from exc
    except urllib.error.URLError:
        raise
    except (ValueError, TypeError) as exc:
        raise ValueError("Invalid URL or failure reaching the server.") from exc

    public_key, private_key = rsa.newkeys(2048)
    hashed_content = sha256(content).digest()

    try:
        signed_hash = rsa.sign(hashed_content, private_key, "SHA-256")
    except rsa.pkcs1.VerificationError:
        raise
    except Exception as exc:
        raise rsa.pkcs1.VerificationError(
            "Failed to sign the SHA256 hash."
        ) from exc

    return public_key, signed_hash.hex(), hashed_content

