import os
import shutil


def task_func(path, delimiter="/"):
    if not isinstance(path, str) or not path:
        raise ValueError("path must be a non-empty string")

    if not isinstance(delimiter, str) or not delimiter:
        raise ValueError("delimiter must be a non-empty string")

    if "\x00" in path:
        raise ValueError("path contains an invalid component")

    if not os.path.exists(path):
        raise FileNotFoundError(path)

    parts = path.split(delimiter)
    is_absolute = path.startswith(delimiter)

    if is_absolute:
        if parts[0] != "":
            raise ValueError("invalid path")
        parts = parts[1:]

    if not parts or any(
        component in ("", ".", "..") for component in parts
    ):
        raise ValueError("path contains invalid components")

    current_path = delimiter if is_absolute else ""
    result = []

    for component in parts:
        current_path = (
            os.path.join(current_path, component)
            if current_path
            else component
        )

        if not os.path.exists(current_path):
            raise FileNotFoundError(current_path)

        usage = shutil.disk_usage(current_path)
        result.append(
            (
                component,
                {
                    "total": usage.total,
                    "used": usage.used,
                    "free": usage.free,
                },
            )
        )

    return result

