import numpy as np
import statsmodels.api as sm


def task_func(
    array: list, random_seed: int = 0
) -> (pd.DataFrame, sm.regression.linear_model.RegressionResultsWrapper):
    if not isinstance(array, list) or not array:
        raise ValueError("array must be a non-empty 2D list.")

    if not all(isinstance(row, list) for row in array):
        raise ValueError("array must be a 2D list.")

    if not all(len(row) == 5 for row in array):
        raise ValueError("Each row must contain exactly five values.")

    try:
        values = np.asarray(array, dtype=float)
    except (TypeError, ValueError) as exc:
        raise ValueError("All values must be numeric.") from exc

    if not np.isfinite(values).all():
        raise ValueError("All values must be finite.")

    np.random.seed(random_seed)

    df = pd.DataFrame(
        values,
        columns=["A", "B", "C", "D", "Response"],
    )

    independent_variables = sm.add_constant(df[["A", "B", "C", "D"]])
    dependent_variable = df["Response"]

