def task_func(file_name):
    import csv

    with open(file_name, mode="r", newline="", encoding="utf-8-sig") as file:
        reader = csv.DictReader(file)

        if reader.fieldnames is None:
            return {}

        counts = {column: collections.Counter() for column in reader.fieldnames}
        has_rows = False

        for row in reader:
            has_rows = True
            for column in reader.fieldnames:
                counts[column][row.get(column, "")] += 1

        if not has_rows:
            return {}

        return {
            column: min(
                counts[column],
                key=lambda value: (-counts[column][value], value)
            )
            for column in reader.fieldnames
        }

