import pandas as pd
import re

# Function to replace acronyms in DataFrame
def task_func(data, mapping):
    if not mapping:
        return data.copy()

    acronyms = sorted(
        (key for key in mapping if isinstance(key, str) and key),
        key=len,
        reverse=True,
    )

    if not acronyms:
        return data.copy()

    pattern = re.compile(
        r"(?<!\w)(?:" + "|".join(re.escape(key) for key in acronyms) + r")(?!\w)"
    )

    def replace_acronyms(value):
        if isinstance(value, str):
            return pattern.sub(lambda match: str(mapping[match.group(0)]), value)
        return value

    return data.apply(lambda column: column.map(replace_acronyms))

