import re
from datetime import time


def task_func(logs: list):
    error_times = []
    time_pattern = re.compile(
        r"(?<!\d)(?:[01]\d|2[0-3]):[0-5]\d(?::[0-5]\d(?:\.\d+)?)?(?!\d)"
    )

    for log in logs:
        if not isinstance(log, str) or not re.search(r"\berror\b", log, re.IGNORECASE):
            continue

        match = time_pattern.search(log)
        if not match:
            continue

        parts = match.group().split(":")
        hour = int(parts[0])
        minute = int(parts[1])
        second = int(float(parts[2])) if len(parts) == 3 else 0
        error_times.append(time(hour, minute, second))

    if not error_times:
        average_time = None
    else:
        total_seconds = sum(
            item.hour * 3600 + item.minute * 60 + item.second
            for item in error_times
        )
        average_seconds = round(total_seconds / len(error_times))
        average_time = time(
            (average_seconds // 3600) % 24,
            (average_seconds % 3600) // 60,
            average_seconds % 60,
        )

    return {"list": error_times, "time": average_time}

import os
import re
from pathlib import Path


def task_func(dir_path: str, predicates: list) -> dict:
    directory = Path(dir_path)
    if not directory.is_dir():
        raise FileNotFoundError(f"Directory does not exist: {dir_path}")

    valid_predicates = []
    seen = set()

    for predicate in predicates:
        if isinstance(predicate, str):
            try:
                compiled = re.compile(predicate)
            except re.error:
                continue
            key = ("regex", compiled.pattern, compiled.flags)
            if key not in seen:
                seen.add(key)
                valid_predicates.append(compiled)
        elif isinstance(predicate, re.Pattern):
            key = ("regex", predicate.pattern, predicate.flags)
            if key not in seen:
                seen.add(key)
                valid_predicates.append(predicate)
        elif callable(predicate):
            key = ("callable", id(predicate))
            if key not in seen:
                seen.add(key)
                valid_predicates.append(predicate)

    if not valid_predicates:
        raise ValueError("No valid predicates were provided")

    result = {}
    for name in os.listdir(directory):
        checks = []
        for predicate in valid_predicates:
            if isinstance(predicate, re.Pattern):
                checks.append(bool(predicate.search(name)))
            else:
                checks.append(bool(predicate(name)))
        result[name] = checks

    return result

