    if df.empty:
        raise ValueError("df must not be empty")
    if col not in df.columns:
        raise ValueError(f"Column '{col}' not found in DataFrame")

    counts = df[col].value_counts()
    if len(counts) > len(COLORS):
        raise ValueError(
            f"The column has {len(counts)} unique values, but only "
            f"{len(COLORS)} predefined colors are available"
        )

    _, ax = plt.subplots()
    ax.pie(counts.values, labels=counts.index, colors=COLORS[:len(counts)])

    if title is not None:
        ax.set_title(title)

    return ax

import os
import shutil

def task_func(src_dir, dest_dir, extension):
    files_moved = 0

    os.makedirs(dest_dir, exist_ok=True)

    if os.path.abspath(src_dir) == os.path.abspath(dest_dir):
        return {"files_moved": 0}

    for entry in os.scandir(src_dir):
        if entry.is_file() and entry.name.endswith(extension):
            shutil.move(entry.path, os.path.join(dest_dir, entry.name))
            files_moved += 1

    return {"files_moved": files_moved}

import random
import re

def task_func(target_words, n_sentences, vocabulary):
    if n_sentences < 0:
        raise ValueError("n_sentences must be non-negative")
    if not vocabulary:
        raise ValueError("vocabulary must not be empty")

    patterns = sorted(
        (str(word) for word in target_words),
        key=len,
        reverse=True,
    )

    target_pattern = None
    if patterns:
        target_pattern = re.compile(
            r"(?<!\w)(?:" + "|".join(re.escape(word) for word in patterns) + r")(?!\w)",
            re.IGNORECASE,
        )

    sentences = []
    for _ in range(n_sentences):
        words = random.choices(vocabulary, k=10)
        sentence = " ".join(str(word) for word in words)

        if target_pattern:
            sentence = target_pattern.sub(
                lambda match: match.group(0).replace(" ", "_"),
