def task_func(
    epoch_milliseconds,
    random_seed=0,
    products=["Product1", "Product2", "Product3", "Product4", "Product5"],
):
    if isinstance(epoch_milliseconds, bool) or not isinstance(
        epoch_milliseconds, (int, float)
    ):
        raise ValueError("epoch_milliseconds must be a number")

    if not math.isfinite(epoch_milliseconds) or epoch_milliseconds < 0:
        raise ValueError("epoch_milliseconds must be a non-negative finite number")

    if not isinstance(products, (list, tuple)) or len(products) != 5:
        raise ValueError("products must contain exactly five products")

    if not all(isinstance(product, str) and product for product in products):
