    try:
        start_datetime = datetime.fromtimestamp(epoch_milliseconds / 1000)
    except (OverflowError, OSError, ValueError) as exc:
        raise ValueError("invalid epoch_milliseconds") from exc

    end_datetime = datetime.now()

    if start_datetime > end_datetime:
        raise ValueError("epoch_milliseconds cannot represent a future time")

    rng = random.Random(random_seed)
    dates = pd.date_range(
        start=start_datetime.date(),
        end=end_datetime.date(),
        freq="D",
    )

    rows = [
        {
            "Product": product,
            "Date": date.to_pydatetime(),
            "Sales": rng.randint(10, 50),
        }
        for date in dates
        for product in products
    ]

