def task_func(
    server_address="localhost", server_port=12345, buffer_size=1024, run_duration=5
):
    start_time = datetime.now()
    duration = max(0, float(run_duration))
    deadline = start_time + timedelta(seconds=duration)

    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    clients = set()
    pending_data = {}

    def close_client(client):
        clients.discard(client)
        pending_data.pop(client, None)
        try:
            client.close()
        except OSError:
            pass

    try:
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.setblocking(False)
        server_socket.bind((server_address, server_port))
        server_socket.listen()

        while datetime.now() < deadline:
            timeout = max(0.0, (deadline - datetime.now()).total_seconds())
            read_sockets = [server_socket, *clients]
            write_sockets = [client for client in clients if pending_data.get(client)]
            exceptional_sockets = [server_socket, *clients]

            try:
                readable, writable, exceptional = select.select(
                    read_sockets,
                    write_sockets,
                    exceptional_sockets,
                    timeout,
                )
            except (OSError, ValueError):
                break

            for sock in exceptional:
                if sock is server_socket:
                    return f"Echo server stopped after {duration:.2f} seconds."
                close_client(sock)

            if server_socket in readable:
                while True:
                    try:
                        client, _ = server_socket.accept()
                        client.setblocking(False)
                        clients.add(client)
                        pending_data[client] = bytearray()
                    except (BlockingIOError, InterruptedError):
                        break
                    except OSError:
                        break

            for client in list(readable):
                if client is server_socket or client not in clients:
                    continue

                try:
                    data = client.recv(buffer_size)
                    if not data:
                        close_client(client)
                        continue

                    response = data + str(datetime.now()).encode()
                    pending_data[client].extend(response)
                except (BlockingIOError, InterruptedError):
                    continue
                except OSError:
                    close_client(client)

            for client in list(writable):
                if client not in clients:
                    continue

                try:
                    sent = client.send(pending_data[client])
                    del pending_data[client][:sent]
                except (BlockingIOError, InterruptedError):
                    continue
                except OSError:
                    close_client(client)

    except OSError as exc:
        return f"Echo server failed: {exc}"
    finally:
        for client in list(clients):
            close_client(client)
        try:
            server_socket.close()
        except OSError:
            pass

    elapsed = (datetime.now() - start_time).total_seconds()
    return f"Echo server operated for {elapsed:.2f} seconds."

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt


def task_func(N=100, CATEGORIES=["A", "B", "C", "D", "E"], seed=42):
    if not isinstance(N, (int, np.integer)) or N < 0:
        raise ValueError("N must be a non-negative integer")

    categories = list(CATEGORIES)
    if N > 0 and not categories:
        raise ValueError("CATEGORIES must not be empty when N is positive")

    rng = np.random.default_rng(seed)

    x = rng.random(N)
    y = rng.random(N)

    if N < len(categories):
        category_values = rng.choice(categories, size=N, replace=False)
    else:
        category_values = categories.copy()
        if N > len(categories):
            category_values.extend(
                rng.choice(categories, size=N - len(categories), replace=True)
            )
        rng.shuffle(category_values)

    df = pd.DataFrame(
        {
            "x": x,
            "y": y,
            "category": category_values,
        }
    )

    category_codes = pd.Categorical(
        df["category"], categories=categories
    ).codes

    ax = df.plot.scatter(
        x="x",
        y="y",
        c=category_codes,
        cmap="viridis",
    )

    return df, ax

import pandas as pd
import numpy as np
import codecs
import re
import datetime


def task_func(start_year=1980, end_year=2000, email_domain='example.com',
              latin_names=['Sopetón', 'Méndez', 'Gómez', 'Pérez', 'Muñoz'],
              other_names=['Smith', 'Johnson', 'Williams', 'Brown', 'Jones'],
              rng_seed=None):
    if start_year > end_year:
        raise ValueError("start_year must not exceed end_year")

    names = list(latin_names) + list(other_names)
    if not names:
        raise ValueError("At least one name must be provided")

    def correct_encoding(name):
        try:
            return codecs.decode(name.encode("latin1"), "utf8")
        except (UnicodeEncodeError, UnicodeDecodeError):
            return name

    def days_in_month(year, month):
        if month == 2:
            leap = year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
            return 29 if leap else 28
        return 30 if month in (4, 6, 9, 11) else 31

    rng = np.random.RandomState(rng_seed)
    selected_names = [
        correct_encoding(str(name))
        for name in rng.choice(names, size=100)
    ]

    dates = []
    for _ in range(100):
        year = int(rng.randint(max(1, start_year), end_year + 1))
        month = int(rng.randint(1, 13))
        day = int(rng.randint(1, days_in_month(year, month) + 1))
        dates.append(datetime.datetime(year, month, day))

    data = {
        "ID": np.arange(1, 101),
        "Name": selected_names,
        "Date of Birth": dates,
        "Email": [
            f"{name.lower()}{date.year}@{email_domain}"
            for name, date in zip(selected_names, dates)
        ],
    }

    return pd.DataFrame(data)

import re
import urllib.parse
import ssl
import socket
import datetime
import tempfile
import os


def task_func(myString):
    result = {}
    urls = re.findall(r"https?://[^\s<>'\"]+", myString, flags=re.IGNORECASE)

    for url in urls:
        url = url.rstrip(".,;:!?)]}")
        try:
            parsed = urllib.parse.urlsplit(url)

            if parsed.scheme.lower() != "https":
                continue

            domain = parsed.hostname
            if not domain:
                continue

            port = parsed.port or 443
            certificate = ssl.get_server_certificate((domain, port))

            temporary_path = None
            try:
                with tempfile.NamedTemporaryFile(
                    mode="w", suffix=".pem", encoding="ascii", delete=False
                ) as temporary_file:
                    temporary_path = temporary_file.name
                    temporary_file.write(certificate)

                certificate_info = ssl._ssl._test_decode_cert(temporary_path)
            finally:
                if temporary_path:
                    try:
                        os.unlink(temporary_path)
                    except OSError:
                        pass

            expiration = ssl.cert_time_to_seconds(
                certificate_info["notAfter"]
            )
            result[domain] = datetime.datetime.fromtimestamp(
                expiration, datetime.timezone.utc
            ).strftime("%Y-%m-%d %H:%M:%S UTC")

        except (
            ssl.SSLError,
            socket.error,
            OSError,
            ValueError,
            KeyError,
        ):
            continue

    return result

