def task_func(df):
    required_columns = {"Title", "Content"}

    if df.empty or not required_columns.issubset(df.columns):
        raise ValueError(
            "The DataFrame must be non-empty and contain 'Title' and 'Content' columns."
        )

    matching_articles = df[
        df["Title"].astype("string").str.contains(
            r"like|what", case=False, na=False, regex=True
        )
    ]

    word_frequency = {}

    for content in matching_articles["Content"].dropna():
        words = re.findall(r"\b\w+\b", str(content).lower())
        for word in words:
            word_frequency[word] = word_frequency.get(word, 0) + 1

    return word_frequency

