from itertools import zip_longest
from random import choices

def task_func(l1, l2, K=10):
    sentinel = object()
    combined = []

    for first, second in zip_longest(l1, l2, fillvalue=sentinel):
        if first is not sentinel:
            combined.append(first)
        if second is not sentinel:
            combined.append(second)

    return collections.Counter(choices(combined, k=K))

from collections import defaultdict
import numpy as np
import matplotlib.pyplot as plt


def task_func(data):
    if not isinstance(data, list):
        raise TypeError("Input must be a list of dictionaries.")
    if not data:
        raise ValueError("Input data must not be empty.")
    if not all(isinstance(item, dict) for item in data):
        raise TypeError("Input must be a list of dictionaries.")

    values_by_key = defaultdict(list)

    for item in data:
        for key, value in item.items():
            if isinstance(value, (bool, np.bool_)) or not np.issubdtype(
                np.asarray(value).dtype, np.number
            ):
                raise TypeError("All dictionary values must be numeric.")
            if not np.isreal(value):
                raise TypeError("All dictionary values must be real numeric values.")
            values_by_key[key].append(value)

    statistics = {}
    axes = []

    for key, values in values_by_key.items():
        mean = float(np.mean(values))
        standard_deviation = float(np.std(values))
        statistics[key] = (mean, standard_deviation)

        _, ax = plt.subplots()
        ax.bar(
            [str(key)],
            [mean],
            yerr=[standard_deviation],
            capsize=5,
        )
        ax.set_title(f"Mean and Standard Deviation for {key}")
        ax.set_ylabel("Value")
        axes.append(ax)

    return statistics, axes

import warnings
import os
import glob
import shutil
import time


def task_func(SOURCE_DIR, DEST_DIR, EXTENSIONS):
    transferred_files = []

    if not isinstance(SOURCE_DIR, (str, os.PathLike)):
        warnings.warn("SOURCE_DIR must be a directory path.")
        return transferred_files

    if not isinstance(DEST_DIR, (str, os.PathLike)):
        warnings.warn("DEST_DIR must be a directory path.")
        return transferred_files

    if not os.path.isdir(SOURCE_DIR):
        warnings.warn(f"Source directory does not exist: {SOURCE_DIR}")
        return transferred_files

    try:
        os.makedirs(DEST_DIR, exist_ok=True)
    except OSError as error:
        warnings.warn(f"Could not create destination directory: {error}")
        return transferred_files

    if isinstance(EXTENSIONS, str):
        extensions = [EXTENSIONS]
    else:
        try:
            extensions = list(EXTENSIONS)
        except TypeError:
            warnings.warn("EXTENSIONS must be a string or an iterable of strings.")
            return transferred_files

    matched_files = set()

    for extension in extensions:
        if not isinstance(extension, str):
            warnings.warn(f"Invalid file extension: {extension!r}")
            continue

        normalized_extension = extension if extension.startswith(".") else f".{extension}"
        pattern = os.path.join(SOURCE_DIR, f"*{normalized_extension}")

        for file_path in glob.glob(pattern):
            if os.path.isfile(file_path):
                matched_files.add(file_path)

    for file_path in sorted(matched_files):
        file_name = os.path.basename(file_path)
        destination_path = os.path.join(DEST_DIR, file_name)

        try:
            shutil.move(file_path, destination_path)
            transferred_files.append(file_name)
        except (OSError, shutil.Error) as error:
            warnings.warn(f"Could not transfer {file_name}: {error}")

    return transferred_files

