def task_func(L, num_dataframes=5, random_seed=None):
    if not L or num_dataframes <= 0:
        return pd.DataFrame(), []

    seed(random_seed)

    column_names = choices("abcdefghijklmnopqrstuvwxyz", k=3)
    df_list = [
        pd.DataFrame(choices(L, k=3), columns=column_names)
        for _ in range(num_dataframes)
