import json
from glob import glob


def task_func(directory, string):
    def contains_string(data):
        if isinstance(data, str):
            return string in data
        if isinstance(data, dict):
            return any(
                contains_string(key) or contains_string(value)
                for key, value in data.items()
            )
        if isinstance(data, list):
            return any(contains_string(item) for item in data)
        return False

    matching_files = []

    for file_path in glob(f"{directory}/**/*.json", recursive=True):
        try:
            with open(file_path, "r", encoding="utf-8") as file:
                data = json.load(file)
        except (OSError, json.JSONDecodeError):
            continue

        if contains_string(data):
            matching_files.append(file_path)

    return matching_files

