import numpy as np
import matplotlib.pyplot as plt
import pandas as pd


def task_func(hex_str):
    if not isinstance(hex_str, str):
        raise ValueError("hex_str must be a valid hex string")

    if "\\x" in hex_str:
        if not hex_str.startswith("\\x") or hex_str.endswith("\\x"):
            raise ValueError("hex_str must be a valid hex string")

        parts = hex_str.split("\\x")
        if parts[0] != "" or any(not part for part in parts[1:]):
            raise ValueError("hex_str must be a valid hex string")

        cleaned = "".join(parts[1:])
    else:
        cleaned = hex_str

    try:
        byte_data = binascii.unhexlify(cleaned)
    except (binascii.Error, ValueError, TypeError) as exc:
        raise ValueError("hex_str must be a valid hex string") from exc

    if cleaned and any(char not in "0123456789abcdefABCDEF" for char in cleaned):
        raise ValueError("hex_str must be a valid hex string")

    values, frequencies = np.unique(
        np.frombuffer(byte_data, dtype=np.uint8),
        return_counts=True,
    )

    dataframe = pd.DataFrame(
        {
            "Byte Value": values,
            "Frequency": frequencies,
        }
    )

    _, ax = plt.subplots()
    ax.bar(dataframe["Byte Value"], dataframe["Frequency"])
    ax.set_xlabel("Byte Value")
    ax.set_ylabel("Frequency")

    return dataframe, ax

