def task_func(vegetable_dict, seed=0):
    """Calculate random counts and percentage occurrences of preferred vegetables."""
    vegetable_to_person = {
        vegetable: person
        for person, vegetable in vegetable_dict.items()
    }

    generator = random.Random(seed)
    counts = {
        vegetable: generator.randint(1, 10)
        for vegetable in vegetable_to_person
