        for vegetable, count in counts.items()
    }

    return pd.DataFrame({
        "Vegetable": list(counts.keys()),
        "Count": list(counts.values()),
        "Percentage": list(percentages.values()),
    })

import json
import os
import re


def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},
            "age": {"type": int},
            "email": {"type": str}
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"
):
    if not os.path.isfile(file_path):
        raise ValueError(f"File does not exist: {file_path}")

    try:
        with open(file_path, "r", encoding="utf-8") as file:
            data = json.load(file)
    except (OSError, json.JSONDecodeError) as error:
        raise ValueError(f"Unable to read valid JSON from file: {file_path}") from error

    if INPUT_JSON.get("type") == "object" and not isinstance(data, dict):
        raise ValueError("JSON root must be an object")

    properties = INPUT_JSON.get("properties", {})
    required = INPUT_JSON.get("required", [])

    for field in required:
        if field not in data:
            raise ValueError(f"Required attribute is missing: {field}")

    for field, schema in properties.items():
        if field not in data:
            continue

        expected_type = schema.get("type")
        value = data[field]

        if isinstance(expected_type, type):
            valid_type = isinstance(value, expected_type)
        else:
            type_map = {
                "string": str,
                "integer": int,
                "number": (int, float),
                "boolean": bool,
                "object": dict,
                "array": list,
                "null": type(None),
            }
            valid_type = isinstance(value, type_map.get(expected_type, object))

        if expected_type is int and isinstance(value, bool):
            valid_type = False

        if not valid_type:
            raise ValueError(f"Invalid type for attribute: {field}")

    if "email" in data and not re.fullmatch(EMAIL_REGEX, data["email"]):
        raise ValueError("Invalid email format")

    if attribute not in data:
        raise ValueError(f"Attribute is missing: {attribute}")

    return data[attribute]

