import pytz
from dateutil import parser

def task_func(date_str, from_tz, to_tz):
    date = parser.parse(date_str)
    source_timezone = pytz.timezone(from_tz)
    target_timezone = pytz.timezone(to_tz)

    if date.tzinfo is None:
        date = source_timezone.localize(date)
    else:
        date = date.astimezone(source_timezone)

    return date.astimezone(target_timezone).strftime("%Y-%m-%d %H:%M:%S")

import numpy as np
from itertools import combinations

def task_func(array1, array2):
    if len(array1) != len(array2):
        raise ValueError("Input arrays must have the same length.")

    if len(array1) == 0:
        return 0

    points = np.column_stack((np.asarray(array1), np.asarray(array2)))

    max_distance = max(
        np.linalg.norm(point_a - point_b)
        for point_a, point_b in combinations(points, 2)
    )

    return float(max_distance)

