import shutil
from pathlib import Path
from typing import List


def task_func(source_dir: str, target_dir: str, extensions: List[str]) -> int:
    source = Path(source_dir)
    target = Path(target_dir)

    if not source.is_dir() or not target.is_dir():
        raise ValueError("source_dir or target_dir does not exist")

    normalized_extensions = {
        extension if extension.startswith(".") else f".{extension}"
        for extension in extensions
        if extension
    }

    moved_count = 0
    for file_path in source.iterdir():
        if file_path.is_file() and file_path.suffix in normalized_extensions:
            shutil.move(str(file_path), str(target))
            moved_count += 1

    return moved_count

import pandas as pd
import folium
from geopy.geocoders import Photon


def task_func(dic):
    geolocator = Photon(user_agent="geoapiExercises")
    locations = []

    if isinstance(dic, pd.DataFrame):
        records = dic.to_dict(orient="records")
        items = [(str(i), record) for i, record in enumerate(records)]
    elif isinstance(dic, dict):
        if {"lat", "lon"}.issubset(dic):
            items = [("Location", dic)]
        else:
            items = list(dic.items())
    else:
        items = list(enumerate(dic))

    def coordinates(value):
        if isinstance(value, dict):
            lat = value.get("lat", value.get("latitude"))
            lon = value.get("lon", value.get("lng", value.get("longitude")))
            if lat is not None and lon is not None:
                return float(lat), float(lon)

            for key in ("address", "location", "place", "name"):
                if key in value:
                    return coordinates(value[key])
            return None

        if isinstance(value, (list, tuple)) and len(value) >= 2:
            try:
                return float(value[0]), float(value[1])
            except (TypeError, ValueError):
                return None

        if isinstance(value, str):
            parts = [part.strip() for part in value.split(",")]
            if len(parts) >= 2:
                try:
                    return float(parts[0]), float(parts[1])
                except ValueError:
                    pass

            try:
                result = geolocator.geocode(value)
            except Exception:
                result = None
            if result is not None:
                return result.latitude, result.longitude

        return None

    for label, value in items:
        point = coordinates(value)
        if point is not None:
            locations.append((str(label), point[0], point[1]))

    center = [locations[0][1], locations[0][2]] if locations else [0, 0]
    map_object = folium.Map(location=center, zoom_start=12 if locations else 2)

    for label, latitude, longitude in locations:
        folium.Marker(
            location=[latitude, longitude],
            popup=label,
            tooltip=label,
        ).add_to(map_object)

    return map_object

import re
import os
import glob
import natsort
import pandas as pd


def task_func(directory='./', file_pattern='*.txt', regex=r'([0-9]+)'):
    if not os.path.isdir(directory):
        raise FileNotFoundError(f"Directory does not exist: {directory}")

    files = glob.glob(os.path.join(directory, file_pattern))
    if not files:
        raise ValueError(f"No files matching pattern found: {file_pattern}")

    rows = []
    for filepath in natsort.natsorted(files):
        with open(filepath, 'r', encoding='utf-8') as file:
            content = file.read()

        matches = []
        for match in re.finditer(regex, content):
            value = match.group(1) if match.lastindex else match.group(0)
            try:
                value = int(value)
            except ValueError:
                try:
                    value = float(value)
                except ValueError:
                    pass
            matches.append(value)

        rows.append({
            'Filename': os.path.basename(filepath),
            'Numeric Data': matches
        })

    return pd.DataFrame(rows, columns=['Filename', 'Numeric Data'])

