import numpy as np
import random
from datetime import datetime
from datetime import timedelta


def task_func(rows=3, columns=2, start_date=datetime(2021, 1, 1), end_date=datetime(2021, 12, 31), seed=0):
    if not isinstance(rows, int) or isinstance(rows, bool) or rows < 0:
        raise ValueError("rows must be a non-negative integer")
    if not isinstance(columns, int) or isinstance(columns, bool) or columns < 0:
        raise ValueError("columns must be a non-negative integer")
    if start_date > end_date:
        raise ValueError("start_date must not be later than end_date")

    count = rows * columns
    available_days = (end_date - start_date).days + 1

    if count > available_days:
        raise ValueError("The date range does not contain enough unique dates")

    rng = random.Random(seed)
    offsets = rng.sample(range(available_days), count)
    dates = [start_date + timedelta(days=offset) for offset in offsets]

    return np.array(dates, dtype=object).reshape(rows, columns)

import re
import os
from collections import Counter

def task_func(folder_path: str) -> dict:
    ip_pattern = re.compile(r"\b(?:\d{1,3}\.){3}\d{1,3}\b")
    counts = Counter()

    if not os.path.isdir(folder_path):
        return {}

    for root, _, files in os.walk(folder_path):
        for filename in files:
            if not filename.lower().endswith(".log"):
                continue

            file_path = os.path.join(root, filename)
            try:
                with open(file_path, "r", encoding="utf-8", errors="ignore") as file:
                    for match in ip_pattern.findall(file.read()):
                        if all(0 <= int(part) <= 255 for part in match.split(".")):
                            counts[match] += 1
            except (OSError, UnicodeError):
                continue

    return dict(counts)

