# Constants
ROOMS = ["Room1", "Room2", "Room3", "Room4", "Room5"]


def task_func(date_str, booking_data):
    if (
        not isinstance(date_str, str)
        or len(date_str) != 10
        or date_str[4] != "-"
        or date_str[7] != "-"
    ):
        raise ValueError("date_str must follow the yyyy-mm-dd format")

    try:
        requested_date = datetime.strptime(date_str, "%Y-%m-%d").date()
    except ValueError as exc:
        raise ValueError("date_str must be a valid date") from exc

    if requested_date < datetime.now().date():
        raise ValueError("date_str must not refer to a past date")

    date_data = booking_data
    if isinstance(booking_data, dict):
        date_data = booking_data.get(date_str, booking_data)

    statuses = {}
    if isinstance(date_data, dict):
        for room in ROOMS:
            value = date_data.get(room, "Available")
            if isinstance(value, bool):
                value = "Booked" if value else "Available"
            statuses[room] = value
    elif isinstance(date_data, (list, tuple, set)):
        booked_rooms = set(date_data)
        statuses = {
            room: "Booked" if room in booked_rooms else "Available"
            for room in ROOMS
        }
    else:
        statuses = {room: "Available" for room in ROOMS}

    report = pd.DataFrame(
        {"Room": ROOMS, "Status": [statuses[room] for room in ROOMS]}
    )

    booked_values = {"booked", "reserved", "occupied", "true", "1"}
    plot_values = [
        1
        if isinstance(status, bool) and status
        or str(status).strip().lower() in booked_values
        else 0
        for status in report["Status"]
    ]

    _, ax = plt.subplots()
    ax.bar(report["Room"], plot_values)
    ax.set_xlabel("Room")
    ax.set_ylabel("Booking Status")
    ax.set_title(f"Room Booking Status for {date_str}")
    ax.set_yticks([0, 1])
    ax.set_yticklabels(["Available", "Booked"])

    return report, ax

