import numpy as np
import itertools
import json


def task_func(data_list, json_file_name="mean_values.json"):
    """Calculate column-wise means and optionally export them to JSON."""
    if not data_list:
        results = {}
    else:
        rows = [
            row if hasattr(row, "__iter__") and not isinstance(row, (str, bytes))
            else [row]
            for row in data_list
        ]

        results = {}
        for index, values in enumerate(itertools.zip_longest(*rows, fillvalue=None)):
            numeric_values = [
                value
                for value in values
                if isinstance(value, (int, float, complex, np.number))
                and not isinstance(value, bool)
                and not (isinstance(value, float) and np.isnan(value))
            ]

            if numeric_values:
                mean = np.mean(numeric_values)
                results[f"Position {index}"] = float(mean)

    if json_file_name is not None:
        with open(json_file_name, "w", encoding="utf-8") as file:
            json.dump(results, file, indent=4)

    return results

