import re
import math
def task_func(s):
    number_pattern = re.compile(
        r"^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$"
    )

    count = 0
    sqrt_sum = 0.0

    for item in s.split(","):
