def task_func(data):
    if len(data) < 2 or data.shape[1] < 2:
        return float("nan")

    columns = {str(column).lower(): column for column in data.columns}

    score_column = next(
        (column for name, column in columns.items() if "score" in name),
        data.columns[0],
    )
    grade_column = next(
        (column for name, column in columns.items() if "grade" in name),
        data.columns[1],
    )

