                scores.extend(value)
            else:
                scores.append(value)
        return sum(scores) / len(scores) if scores else float("nan")

    average_scores_series = (
        df.groupby("Name")["Scores"]
        .apply(average_scores)
    )

    most_common_age = None
    if not df.empty:
        most_common_age = int(Counter(df["Age"].tolist()).most_common(1)[0][0])

    return sorted_df, average_scores_series, most_common_age

import json
import os

# Constants
PREFIXES = ["is_", "has_", "can_", "should_"]


def task_func(directory):
    """Count keys beginning with each configured prefix in JSON files."""
    statistics = {prefix: 0 for prefix in PREFIXES}

    def count_keys(value):
        if isinstance(value, dict):
            for key, nested_value in value.items():
                if isinstance(key, str):
                    for prefix in PREFIXES:
                        if key.startswith(prefix):
                            statistics[prefix] += 1
                count_keys(nested_value)
        elif isinstance(value, list):
            for item in value:
                count_keys(item)

    for filename in os.listdir(directory):
        if filename.lower().endswith(".json"):
            filepath = os.path.join(directory, filename)
            if os.path.isfile(filepath):
                with open(filepath, "r", encoding="utf-8") as file:
                    count_keys(json.load(file))

    return statistics

