import json
from datetime import datetime
import numpy as np
from decimal import Decimal


class CustomJSONEncoder(json.JSONEncoder):
    def default(self, obj):
        if isinstance(obj, datetime):
            return obj.isoformat()
        if isinstance(obj, np.ndarray):
            return obj.tolist()
        if isinstance(obj, Decimal):
            return float(obj)
        if isinstance(obj, np.generic):
            return obj.item()
        return super().default(obj)


def task_func(my_obj):
    return json.dumps(my_obj, cls=CustomJSONEncoder)

from itertools import groupby
from operator import itemgetter

# Constants
KEY_FUNC = itemgetter(0)


def task_func(my_dict):
    sorted_items = sorted(my_dict.items(), key=lambda item: KEY_FUNC(item[0]))

    aggregated_dict = {
        first_char: sum(value for _, value in group)
        for first_char, group in groupby(
