import numpy as np
from sklearn.preprocessing import StandardScaler
from sklearn.metrics import mean_squared_error


def task_func(num_samples=1000, k=5, d=2, random_seed=None):
    if random_seed is not None:
        np.random.seed(random_seed)

    data = np.random.randn(num_samples)
    transformed_data = k * data + d

    scaler = StandardScaler()
    standardized_data = scaler.fit_transform(
        transformed_data.reshape(-1, 1)
    ).ravel()

    return float(mean_squared_error(transformed_data, standardized_data))

import pandas as pd
import os


def task_func(
    original_file_location="test.xlsx",
    new_file_location="new_test.xlsx",
    sheet_name="Sheet1",
):
    if not os.path.isfile(original_file_location):
        raise FileNotFoundError(original_file_location)

    with pd.ExcelFile(original_file_location) as workbook:
        if sheet_name not in workbook.sheet_names:
            raise ValueError(f"Sheet '{sheet_name}' does not exist in the workbook.")
        data = pd.read_excel(workbook, sheet_name=sheet_name)

    data.to_excel(new_file_location, sheet_name=sheet_name, index=False)
    return pd.read_excel(new_file_location, sheet_name=sheet_name)

